parts.text:
{
  "feasible": true,
  "summary": "Se añade un botón en el detalle de un presupuesto para duplicarlo, creando un nuevo presupuesto en estado borrador con el mismo cliente y sus líneas de detalle.",
  "assumptions": [
    "El número de presupuesto nuevo se genera automáticamente con la función de numeración existente.",
    "La fecha de emisión del presupuesto duplicado será la fecha actual del sistema.",
    "El presupuesto duplicado se crea en estado borrador (draft)."
  ],
  "tasks": [
    {
      "title": "Añadir acción de duplicar presupuesto en el servidor",
      "description": "Crea una server action en src/app/(crm)/presupuestos/actions.ts llamada duplicateQuote que reciba el id de un presupuesto existente, consulte sus datos y sus líneas (quoteItems), genere un nuevo número con nextDocumentNumber, inserte el nuevo presupuesto con estado 'draft' y fecha actual, inserte sus líneas asociadas y redirija al detalle del nuevo presupuesto recién creado.",
      "files": [
        "src/app/(crm)/presupuestos/actions.ts"
      ],
      "references": [
        "src/app/(crm)/presupuestos/actions.ts",
        "src/app/(crm)/presupuestos/queries.ts"
      ],
      "acceptanceCriteria": [
        {
          "id": "c1",
          "type": "e2e",
          "text": "El detalle del presupuesto muestra el botón para duplicar con data-testid duplicate-quote-button.",
          "testIds": [
            "duplicate-quote-button"
          ]
        },
        {
          "id": "c2",
          "type": "e2e",
          "text": "Al pulsar duplicar en un presupuesto, se crea uno nuevo en borrador y se redirige a su detalle mostrando el estado borrador y las mismas líneas.",
          "testIds": [
            "duplicate-quote-button",
            "quote-detail",
            "status-badge",
            "items-table",
            "item-row"
          ]
        }
      ]
    },
    {
      "title": "Añadir el botón de duplicar en la vista de detalle de presupuesto",
      "description": "Modifica src/app/(crm)/presupuestos/[id]/page.tsx para incluir el componente de botón que invoque la acción de duplicación con el data-testid duplicate-quote-button, integrándolo junto a los demás botones de acción del detalle.",
      "files": [
        "src/app/(crm)/presupuestos/[id]/page.tsx"
      ],
      "references": [
        "src/app/(crm)/presupuestos/[id]/page.tsx",
        "src/app/(crm)/facturas/[id]/page.tsx"
      ],
      "acceptanceCriteria": [
        {
          "id": "c3",
          "type": "e2e",
          "text": "La página de detalle del presupuesto contiene el botón duplicate-quote-button junto al resto de controles.",
          "testIds": [
            "quote-detail",
            "duplicate-quote-button"
          ]
        }
      ]
    }
  ]
}
